const D = { density: .5, energy: .65, scale: 1, speed: 1, hue: 30, gravity: .5, decay: .5, style: 'phosphor', act: 'finale', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const eo = p => 1 - (1 - p) * (1 - p);
const u = Math.min(width, height);
const t = K.t;
const sty = P.style;
const add = (sty === 'phosphor' || sty === 'thermal' || sty === 'pixel');

// section-arcI program (multi-minute dramaturgy)
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { finale:{load:1.15,size:1.15}, volley:{load:.85,size:1.0}, ember:{load:.6,size:.8} };
const ac = ACT[P.act] || ACT.finale;
const arcI = 0.7 + 0.5 * K.intensity * ac.load;

const nSh = Math.max(4, Math.round((6 + P.density * 10) * ac.load));
const scl = P.scale;
const gravK = 0.12 + P.gravity * 1.1;
const fadePow = 0.5 + P.decay * 1.9;
const cnt = Math.floor((16 + P.energy * 20) * (sty === 'blueprint' ? 0.55 : 1));

push();
noStroke();
if (add) blendMode(ADD);

// ---- persistent drifting ember + smoke haze (continuous, K.t-driven, never re-phases) ----
const nem = Math.floor((22 + P.density * 46));
for (let i = 0; i < nem; i++) {
  const spd = 0.03 + 0.07 * fr(i + 401);
  const life = ((fr(i * 2 + 200) + t * spd * P.speed) % 1 + 1) % 1;
  const ex = (((fr(i * 3 + 202) + Math.sin(t * 0.15 + i) * 0.03) % 1) + 1) % 1 * width;
  const ey = (0.2 + life * 0.8) * height;
  const flick = 0.55 + 0.45 * Math.sin(t * 5 + i * 1.7);
  const eh = hw(P.hue + (fr(i + 203) - 0.5) * 70);
  const ea = (0.35 + 0.65 * (1 - life)) * (16 + 18 * flick) * (0.5 + 0.5 * P.energy);
  const esz = u * 0.009 * (0.7 + flick) * scl;
  if (sty === 'ink') fill(hw(P.hue + 20), 8, 88, ea * 0.7);
  else if (sty === 'thermal') fill(hw(18 + (1 - life) * 44), 88, 100, ea);
  else if (sty === 'blueprint') { stroke(hw(P.hue + 185), 30, 100, ea * 0.8); strokeWeight(1); point(ex, ey); noStroke(); continue; }
  else fill(eh, 55, 100, ea);
  ellipse(ex, ey, esz, esz);
}

// ---- deterministic staggered shells: always several rising / mid-burst ----
for (let s = 0; s < nSh; s++) {
  const o1 = fr(s * 4 + 11), o2 = fr(s * 4 + 12), o3 = fr(s * 4 + 13), o4 = fr(s * 4 + 14), o5 = fr(s * 7 + 15);
  const freq = (0.14 + o1 * 0.20) * P.speed;
  const ph = t * freq + o2;
  const p = ph - Math.floor(ph);
  const lx = width * (0.09 + o3 * 0.82);
  const ty = height * (0.13 + o4 * 0.40);
  const shue = hw(P.hue + (o5 - 0.5) * 130);
  const pr = 0.24;

  if (p < pr) {
    // ---- rising rocket ----
    const rp = p / pr;
    const ry = height * 1.05 + (ty - height * 1.05) * eo(rp);
    const ra = (28 + A.treble * 20) * (0.5 + 0.5 * rp);
    const rsz = u * 0.007 * scl;
    if (sty === 'blueprint') {
      stroke(hw(P.hue + 185), 22, 100, 40); strokeWeight(1); noFill();
      line(lx, ry, lx, Math.min(height * 1.05, ry + u * 0.06)); noStroke();
    } else if (sty === 'ink') {
      fill(hw(P.hue + 20), 6, 90, ra * 0.8); ellipse(lx, ry, rsz * 1.6, rsz * 3);
    } else {
      fill(shue, 45, 100, ra); ellipse(lx, ry, rsz, rsz * 2.4);
      fill(hw(shue + 20), 25, 100, ra * 0.5); ellipse(lx, ry + rsz * 2, rsz * 0.8, rsz * 4);
    }
  } else {
    // ---- explosion ----
    const tb = (p - pr) / (1 - pr);
    const maxR = u * (0.09 + P.energy * 0.15) * scl * (0.7 + o1 * 0.6) * ac.size * arcI;
    const expand = 1 - Math.pow(1 - tb, 2.2);
    const droop = gravK * maxR * tb * tb;
    const aBurst = Math.pow(1 - tb, fadePow);
    const kick = K.pulse * 0.25 + A.bass * 0.4;
    // central flash (partial, early only)
    if (tb < 0.22) {
      const fa = (1 - tb / 0.22) * (30 + kick * 30);
      if (sty !== 'blueprint' && sty !== 'ink') { fill(hw(shue + 25), 18, 100, fa); ellipse(lx, ty, maxR * 0.5, maxR * 0.5); }
    }
    for (let k = 0; k < cnt; k++) {
      const an = (k / cnt) * TAU + o2 * TAU;
      const sk = 0.5 + fr(s * 40 + k) * 0.7;
      const rr = maxR * expand * sk;
      const px = lx + Math.cos(an) * rr;
      const py = ty + Math.sin(an) * rr + droop;
      const tw = 0.6 + 0.4 * Math.sin(t * 9 + k * 1.3 + s);
      const al = aBurst * (30 + A.treble * 18) * tw * (0.7 + 0.5 * kick);
      const sz = u * 0.007 * scl * (0.55 + aBurst * 0.9);
      if (sty === 'blueprint') {
        stroke(hw(P.hue + 185 + (1 - aBurst) * 40), 26, 100, al * 1.5); strokeWeight(1.2); noFill();
        line(lx, ty, px, py);
        ellipse(px, py, sz * 1.6, sz * 1.6); noStroke();
      } else if (sty === 'ink') {
        const spread = 1 + (1 - aBurst) * 1.5;
        fill(hw(P.hue + 20), 7, 92, al * 1.1); ellipse(px, py, sz * spread, sz * spread);
      } else if (sty === 'thermal') {
        fill(hw(60 - aBurst * 60), 92, 100, al); ellipse(px, py, sz, sz);
      } else if (sty === 'pixel') {
        const g = u * 0.013 * scl;
        const gx = Math.round(px / g) * g, gy = Math.round(py / g) * g;
        fill(shue, 70, 100, al); rect(gx - g * 0.4, gy - g * 0.4, g * 0.8, g * 0.8);
      } else {
        fill(shue, 42, 100, al * 0.55); ellipse(px, py, sz * 2.3, sz * 2.3);
        fill(hw(shue + 18), 16, 100, al); ellipse(px, py, sz, sz);
      }
    }
    // burst smoke puff (fades late)
    if (sty === 'ink' || sty === 'thermal') {
      fill(sty === 'ink' ? hw(P.hue) : hw(shue + 20), sty === 'ink' ? 6 : 20, sty === 'ink' ? 70 : 45, aBurst * 10);
      ellipse(lx, ty - u * 0.02 * tb, maxR * (0.8 + tb), maxR * (0.8 + tb));
    }
  }
}

if (add) blendMode(BLEND);
pop();
drawingContext.shadowBlur = 0;
